<script setup lang="ts">
import {ref,nextTick,watch,onBeforeUnmount} from 'vue'
import {RouterLink,useRoute} from 'vue-router'
import {useApp} from '../stores/app'
import '../styles/public-chatbot.css'
const app=useApp(),dialog=ref<HTMLDialogElement>(),entry=ref(''),messages=ref<{role:string;text:string}[]>([]),launcher=ref<HTMLButtonElement>()
const route=useRoute(),panelWidth=ref(560),messageList=ref<HTMLOListElement>()
function fitPanel(){const pane=document.querySelector<HTMLElement>('.page-c-map .app>aside:not([hidden]),.page-c-live-map .map-sidebar');const rect=pane?.getBoundingClientRect();panelWidth.value=window.innerWidth<=700?Math.min(window.innerWidth,dialog.value?.open?dialog.value.getBoundingClientRect().right:document.documentElement.clientWidth):rect&&rect.left>window.innerWidth*.45?Math.min(window.innerWidth,Math.max(340,(dialog.value?.open?dialog.value.getBoundingClientRect().right:document.documentElement.clientWidth)-rect.left)):Math.min(600,window.innerWidth)}
async function open(){fitPanel();dialog.value?.showModal();window.addEventListener('resize',fitPanel);await nextTick();fitPanel();await nextTick();dialog.value?.querySelector('input')?.focus({preventScroll:true})}
function close(){dialog.value?.close();window.removeEventListener('resize',fitPanel);launcher.value?.focus({preventScroll:true})}
function outside(event:MouseEvent){if(event.target!==dialog.value)return;const rect=dialog.value.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)close()}
watch(()=>route.fullPath,close)
watch(()=>messages.value.length,async()=>{await nextTick();messageList.value?.scrollTo({top:messageList.value.scrollHeight})})
onBeforeUnmount(()=>window.removeEventListener('resize',fitPanel))
function send(){const question=entry.value.trim();if(!question)return;messages.value.push({role:'이용자',text:question});entry.value='';const privateQuestion=/(내\s*(차량|문의|계정|정보|연락처)|개인정보|전화번호)/.test(question);const faq=app.faqs.find(f=>f.question===question);const answer=privateQuestion&&!app.account?'먼저 로그인해 주세요.':privateQuestion?'개인정보 조회 서비스 연결이 필요합니다.':faq?.answer||'등록된 FAQ에서 답변을 찾지 못했습니다. 공지·FAQ 또는 문의하기를 확인해 주세요.';messages.value.push({role:'안내',text:answer})}
</script>
<template><button ref="launcher" class="public-chat-launcher" type="button" aria-haspopup="dialog" @click="open">챗봇 문의</button><dialog ref="dialog" class="drawer-dialog public-chat-dialog" :style="{width:panelWidth+'px'}" aria-labelledby="public-chat-title" @cancel.prevent="close" @click="outside"><header class="public-chat-header"><div><small>ROUTEL HELP</small><h2 id="public-chat-title">ROUTEL 이용 안내</h2></div><button type="button" aria-label="챗봇 닫기" @click="close">×</button></header><p class="public-chat-description">등록된 FAQ를 안내합니다. 자유 질문 자동 답변은 서비스 연결 후 제공됩니다.</p><ol ref="messageList" class="chat-messages" aria-live="polite"><li v-if="!messages.length" class="public-chat-welcome"><b>무엇을 도와드릴까요?</b><p>궁금한 내용을 아래에 입력해 주세요.</p><RouterLink to="/info/faq">자주 묻는 질문 확인 →</RouterLink></li><li v-for="(m,i) in messages" :key="i" :class="{'is-user':m.role==='이용자'}"><b>{{m.role}}</b><p>{{m.text}}</p></li></ol><form class="public-chat-form" @submit.prevent="send"><label for="public-chat-input">질문</label><div class="public-chat-compose"><input id="public-chat-input" v-model="entry" placeholder="궁금한 내용을 입력하세요" autocomplete="off" required><button type="submit">보내기</button></div><nav aria-label="챗봇 이용 안내"><RouterLink to="/c-notice">공지사항</RouterLink><RouterLink to="/info/faq">FAQ</RouterLink><RouterLink to="/my-inquiries">문의하기</RouterLink></nav></form></dialog></template>
